 if(c==1||c==5||c==9)program(GL_VERTEX_PROGRAM_ARB,"!!ARBvp1.0\nMOV result.position,vertex.position;\nMOV result.color,vertex.color;\nMOV result.texcoord[0],vertex.texcoord[0];\nMOV result.texcoord[1],vertex.texcoord[1];\nEND\n");
